Contract ProcessSaleService::makeNewSale(): Boolean {

            precondition:
          CurrentCashDesk.oclIsUndefined() = false and (CurrentSale.oclIsUndefined() = true or CurrentSale.IsComplete = true)

            postcondition:
          result = true and CurrentSale.oclIsNew() = true and CurrentSale.IsComplete = false and CurrentSale.IsReadytoPay = false

        }
